// ══════════════════════════════════════════════════════════
// Model Library — loads the embedded real glTF character models
// (see src/data/generatedModels.js, auto-generated by
// tools/embed-models.mjs) once, and hands out cheap per-instance
// clones with their own AnimationMixer/actions.
//
// Deferred-init, same shape as ParticleBursts.js: the constructor
// does nothing but set up an empty Map. Decoding base64 + parsing a
// GLB is async work, and this module can be imported (constructing
// the singleton) well before there's anywhere useful to put the
// result — so the real work lives in preload(), called explicitly
// from main.js's initGame().
// ══════════════════════════════════════════════════════════

import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import { clone as cloneSkinned } from 'three/examples/jsm/utils/SkeletonUtils.js';
import { AnimationMixer, CanvasTexture, Color } from 'three';
import { MODEL_REGISTRY } from '../data/generatedModels.js';

// Every embedded GLB is written by tools/embed-models.mjs through
// gltf-transform, which emits EXT_meshopt_compression — without a
// decoder registered, GLTFLoader rejects the file outright with
// "setMeshoptDecoder must be called before loading compressed files".
//
// That failure is why this whole system was silently dead: preload()
// catches per-entry and console.warn()s, so all 34 models failed,
// every caller's isReady() returned false, and every call site quietly
// took its procedural fallback path. The game looked like it had no
// real models because, at runtime, it didn't. One shared loader, with
// the decoder attached once, is the fix.
//
// (KHR_mesh_quantization and EXT_texture_webp — also required by these
// files — need no setup; GLTFLoader handles both natively.)
const _loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);

/** base64 -> ArrayBuffer, standard browser-safe pattern (no Buffer/Node APIs). */
function base64ToArrayBuffer(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

// ── Real-model texture grime pass ────────────────────────────
//
// The KayKit source textures are a bright, saturated "toy" colour
// swatch (peachy skin, poster-red cape, gold-yellow trim, sky-blue
// armour) that reads as a completely different visual language from
// this game's already-dark procedural creatures/props. The geometry
// is genuinely clean — it's purely a colour/material problem — so we
// fix it once, here, on the shared TEMPLATE the moment its glTF is
// parsed. Every future SkeletonUtils.clone() draws from this same
// template, so darkening it once darkens every instance for free.
//
// This game's established dark-fantasy tone (style.css tokens: tarnished
// gold #6b5228, dried-blood red #8f1616, near-black ground #0a0806) is
// the target direction: desaturated, warm-dark, "tarnished metal and
// dried blood" rather than "bright toy paint".
const _GRIME_TINT = new Color(0x453a2c); // warm dark grey — tarnished-metal direction, not neutral grey

/**
 * Draws `texture.image` onto an offscreen canvas, desaturates +
 * darkens it, composites a subtle multiply-blended grime pass, and
 * returns a new CanvasTexture with the original's colour-managed
 * sampling settings copied over. Never throws by itself — callers
 * wrap this per-material so one bad texture never blocks the rest.
 */
function _darkenTexture(texture) {
  const img = texture.image;
  const w = img && img.width;
  const h = img && img.height;
  if (!w || !h) return texture; // nothing decoded yet / not an image-backed texture — leave as-is

  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');

  // Pass 1 — desaturate + darken. Canvas `filter` compositing is the
  // cheap equivalent of a per-pixel lerp-to-luminance + RGB multiply;
  // this project renders as a Chromium single-file artifact, so
  // `ctx.filter` support is safe to rely on here.
  // ⚠️ Owner: the KayKit enemies "were way better before" — this pass
  // plus the colour tint below crushed them to black silhouettes. Kept
  // only as a light weathering now.
  ctx.filter = 'saturate(88%) brightness(96%)';
  ctx.drawImage(img, 0, 0, w, h);
  ctx.filter = 'none';

  // Pass 2 — subtle weathering. Scatter soft-edged radial-gradient
  // blotches, multiply-blended, at low opacity. This is a small flat-
  // colour palette-swatch atlas (each block = one body part), so this
  // is deliberately restrained — "weathered", not "filthy" — to avoid
  // reading as dirt smudged onto the wrong material.
  ctx.globalCompositeOperation = 'multiply';
  const blobCount = 15 + Math.floor(Math.random() * 15); // 15-29
  const maxDim = Math.max(w, h);
  for (let i = 0; i < blobCount; i++) {
    const cx = Math.random() * w;
    const cy = Math.random() * h;
    const r = (0.035 + Math.random() * 0.09) * maxDim;
    const alpha = 0.05 + Math.random() * 0.09; // subtle: ~0.05-0.14
    const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
    grad.addColorStop(0, `rgba(18, 15, 11, ${alpha})`);
    grad.addColorStop(1, 'rgba(18, 15, 11, 0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';

  const out = new CanvasTexture(canvas);
  // Match the original's colour-managed sampling — getting this wrong
  // (e.g. missing sRGB) makes the model look washed-out or double-dark
  // rather than the intended treatment.
  out.colorSpace = texture.colorSpace;
  out.flipY = texture.flipY;
  out.wrapS = texture.wrapS;
  out.wrapT = texture.wrapT;
  out.needsUpdate = true;
  return out;
}

/**
 * Nudges a material's base `.color` toward this game's desaturated,
 * warm-dark palette. Layered ON TOP of the texture treatment above,
 * not instead of it — the texture carries the grime, this carries the
 * overall tint.
 */
function _tintColorDark(color) {
  const hsl = { h: 0, s: 0, l: 0 };
  color.getHSL(hsl);
  // ⚠️ A textured material's base colour MULTIPLIES its texture; the old
  // ×0.75 + grime lerp left it at ~0x38 and the model unreadable. Start
  // from white and only warm it a touch.
  void hsl;
  color.setRGB(1, 1, 1);
  color.lerp(_GRIME_TINT, 0.06);
}

/**
 * Walks a parsed template scene ONCE and grimes every material that
 * carries a base-colour texture. Called exactly once per template
 * (from preload(), before the template is cached) — never per-clone,
 * per the perf note in the header above.
 *
 * Defensive per-material: one malformed material is warned about and
 * left untouched rather than aborting the whole model.
 */
function _darkenTemplateMaterials(scene) {
  scene.traverse((obj) => {
    if (!obj.isMesh || !obj.material) return;
    const materials = Array.isArray(obj.material) ? obj.material : [obj.material];
    for (const material of materials) {
      try {
        if (!material) continue;

        if (material.map) {
          material.map = _darkenTexture(material.map);
        }

        if (material.color) _tintColorDark(material.color);

        // Matte reads as "real material"; only nudge if it's currently
        // low/glossy — don't blindly overwrite an already-reasonable value.
        if (typeof material.roughness === 'number' && material.roughness < 0.55) {
          material.roughness = Math.min(1, material.roughness + 0.25);
        }

        material.needsUpdate = true;
      } catch (err) {
        console.warn(`[ModelLibrary] failed to grime material "${material && material.name}":`, err);
      }
    }
  });
}

class ModelLibrary {
  constructor() {
    this._templates = new Map(); // key -> { scene, animations }
  }

  /**
   * Decode + parse every model in MODEL_REGISTRY in parallel. Never
   * throws — a single bad/missing model is caught, warned about, and
   * simply left out of the Map so callers can detect "not available"
   * (getTemplate returns null) and fall back safely instead of one
   * broken asset taking down boot.
   */
  async preload() {
    const keys = Object.keys(MODEL_REGISTRY);
    await Promise.all(keys.map(async (key) => {
      try {
        const base64 = MODEL_REGISTRY[key];
        const arrayBuffer = base64ToArrayBuffer(base64);
        const gltf = await _loader.parseAsync(arrayBuffer, '');

        // Darken/desaturate/grime the template's materials ONCE, here —
        // see _darkenTemplateMaterials' doc comment. Wrapped in its own
        // try/catch (on top of the per-material one inside it) so a
        // total failure of the grime pass still leaves the model usable
        // in its original (bright) colours rather than losing it entirely.
        //
        // EXCEPTION: `item:*` keys whose name contains "potion" are
        // skipped entirely. Unlike the Knight/Skeleton_Warrior `model:*`
        // templates (bright "toy" source textures that genuinely needed
        // pulling toward this game's dark tone) and the `prop:*` MegaKit
        // furniture/weapon/lighting props (tarnished metal / weathered
        // wood is the *correct* direction for those), potion/elixir
        // models' whole visual job is vivid, legible liquid colour (red
        // health / blue mana / green-purple poison — see ELEMENT_COLORS in
        // src/data/constants.js for this game's existing colour-coding
        // convention). Desaturating + darkening + grime-blotching that
        // liquid colour would muddy exactly the distinction that makes
        // potions readable at a glance — a real regression, not a
        // stylistic loss.
        //
        // Deliberately NOT a blanket `key.startsWith('item:')` skip: the
        // `item:` category also holds non-potion pieces (e.g.
        // `item:grimoire___morphose`, a spellbook) that are exactly the
        // kind of worn-object asset the grime pass is *for*, same as the
        // prop:Book_Stack_1 / prop:Bookcase_2 props. A prefix-wide
        // exemption would silently under-groom those too. Matching on the
        // "potion" substring instead means a future teammate adding
        // another `item:*_potion_*`/`item:potion_*` model gets the right
        // "leave it vivid" default automatically, while any other new
        // `item:*` asset still gets full grooming unless it also reads as
        // a colour-coded liquid.
        const skipGrime = key.startsWith('item:') && key.toLowerCase().includes('potion');
        if (!skipGrime) {
          try {
            _darkenTemplateMaterials(gltf.scene);
          } catch (err) {
            console.warn(`[ModelLibrary] texture grime pass failed for "${key}", using original textures:`, err);
          }
        }

        if (key.startsWith('atlas:')) {
          this._registerAtlas(key, gltf);
        } else {
          this._templates.set(key, { scene: gltf.scene, animations: gltf.animations });
        }
      } catch (err) {
        console.warn(`[ModelLibrary] failed to load model "${key}":`, err);
      }
    }));
  }

  /**
   * Expand an atlas GLB into one template per prop.
   *
   * tools/extract-megakit.sh merges the MegaKit into a single file with
   * one Scene per prop, so the four shared trim-sheet material sets are
   * stored once instead of being duplicated into ~94 separate files
   * (8.5 MB the old way for only 61 props; 3.7 MB this way for all 94).
   *
   * glTF scene NAMES are useless here — every source file called its
   * scene "Scene", and merge preserved that verbatim — but each scene's
   * single root node still carries the real prop name ("Cauldron",
   * "Bed_Twin1", ...). So key off the root node, not the scene.
   *
   * Registers each as "prop:<RootNodeName>", which is exactly the key
   * shape call sites already use, so nothing downstream had to change
   * when the storage format did.
   */
  _registerAtlas(atlasKey, gltf) {
    const scenes = gltf.scenes || (gltf.scene ? [gltf.scene] : []);
    let added = 0;
    for (const scene of scenes) {
      const root = scene.children && scene.children.length === 1 ? scene.children[0] : scene;
      const name = root && root.name;
      if (!name) continue;
      // Animations live on the atlas as a whole; props are static, so
      // handing each an empty list is correct rather than lossy.
      this._templates.set(`prop:${name}`, { scene, animations: [] });
      added++;
    }
    console.log(`[ModelLibrary] ${atlasKey}: registered ${added} props`);
  }

  /**
   * Load models from URLs instead of the base64-embedded registry.
   *
   * The embedded registry exists to satisfy the Claude Artifact's
   * "zero external requests" constraint, and it costs a 33% base64
   * inflation plus a synchronous decode of every byte at boot. The HD
   * build has no such constraint, and the photoscanned nature set is
   * ~10MB — embedding that would add ~13MB to the bundle and several
   * hundred milliseconds of decode for no benefit.
   *
   * Fetched over HTTP instead: no inflation, the browser caches them,
   * and they download in parallel with everything else.
   *
   * Resolves even if some or all fail. A missing nature model must
   * degrade to the procedural prop, never break world generation.
   *
   * @param {string} baseUrl   e.g. 'hd/nature'
   * @param {string[]} slugs   filenames without .glb
   * @param {string} prefix    registry key prefix, e.g. 'nature'
   * @param {object} opts
   * @param {boolean} opts.grime  run the darken/desaturate pass
   * @returns {Promise<number>} how many loaded successfully
   */
  async preloadExternal(baseUrl, slugs, prefix, { grime = false } = {}) {
    let loaded = 0;
    await Promise.all(slugs.map(async (slug) => {
      const key = `${prefix}:${slug}`;
      try {
        const res = await fetch(`${baseUrl}/${slug}.glb`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const buf = await res.arrayBuffer();
        const gltf = await _loader.parseAsync(buf, '');

        // Grime is OFF by default for this path, and that is the point
        // for the nature set specifically: those models are
        // photogrammetry of real rock and dead wood. Their colour and
        // tonal range ARE the realism being bought. The grime pass
        // exists to drag KayKit's bright toy-coloured texturing toward
        // this game's palette — applying it to a photoscan would
        // destroy exactly the quality it was fetched for. Mood is
        // handled downstream by CinematicGrade instead.
        if (grime) {
          try { _darkenTemplateMaterials(gltf.scene); }
          catch (err) { console.warn(`[ModelLibrary] grime failed for "${key}":`, err); }
        }

        this._templates.set(key, { scene: gltf.scene, animations: gltf.animations || [] });
        loaded++;
      } catch (err) {
        console.warn(`[ModelLibrary] external model "${key}" unavailable:`, err.message);
      }
    }));
    console.log(`[ModelLibrary] ${loaded}/${slugs.length} external "${prefix}:" models loaded`);
    return loaded;
  }

  /** Synchronous, safe to call anytime. Null if not preloaded/available. */
  getTemplate(key) {
    return this._templates.get(key) || null;
  }

  /** Convenience bool — !!getTemplate(key). */
  isReady(key) {
    return !!this.getTemplate(key);
  }

  /**
   * Returns a fresh, independently-animatable instance of `key`, or
   * null if the template isn't loaded/available.
   *
   * Uses SkeletonUtils.clone rather than Object3D.clone() — plain
   * clone() does not correctly rebind skinned-mesh bone references
   * (a well-known three.js pitfall), so every clone would end up
   * sharing/fighting over the source skeleton's bones.
   */
  instantiate(key, opts = {}) {
    const template = this.getTemplate(key);
    if (!template) return null;

    const group = cloneSkinned(template.scene);
    group.traverse((o) => {
      if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; }
    });

    const mixer = new AnimationMixer(group);
    const actions = new Map();
    for (const clip of template.animations) {
      actions.set(clip.name, mixer.clipAction(clip, group));
    }

    return { group, mixer, actions };
  }
}

export const modelLibrary = new ModelLibrary();
